package org.json;import java.util.*;public class JSONArray{static final Map<String,List<JSONObject>> snaps=new HashMap<>();final List<JSONObject> v=new ArrayList<>();public JSONArray(){}public JSONArray(String s)throws JSONException{if(s!=null&&!s.equals("[]")){for(JSONObject o:snaps.getOrDefault(s,List.of()))v.add(o.copy());}}public JSONArray put(JSONObject o){v.add(o);return this;}public int length(){return v.size();}public JSONObject optJSONObject(int i){return i>=0&&i<v.size()?v.get(i):null;}public JSONObject remove(int i){return v.remove(i);}public String toString(){String key="v"+UUID.randomUUID();List<JSONObject> c=new ArrayList<>();for(JSONObject o:v)c.add(o.copy());snaps.put(key,c);return key;}}